gs": [{"quantity": "节点高度 h", "mark": "文本（浅色小字）", "where": "每个节点圆上方"}, {"quantity": "平衡因子 BF", "mark": "文本（粗体大字）", "where": "每个节点圆下方"}, {"quantity": "BF 是否超出范围", "mark": "节点填充色（白/红）", "where": "节点圆本身"}, {"quantity": "当前选中节点", "mark": "加粗边框", "where": "节点圆边框"}], "comparison_states": [], "interaction_loop": {"action": "点击节点圆选择节点，或点击「切换不平衡」按钮改变整树结构", "model_update": "selectedNode 更新为点击的节点 id；treeStructure 在三个预设值间循环", "visible_change": "选中节点边框加粗；不平衡状态下部分节点 BF 变为 2 或 -2，节点变红，h 值重新计算", "history": "每次切换 treeStructure 时，前一结构的节点位置和数值被完全替换，无渐变过渡；选中节点在切换后保持选中（若存在）", "reset": "点击「重置」按钮将 treeStructure 设回 'balanced'，selectedNode 设回 'root'"}, "math_model": {"formula": "BF(node) = height(left_subtree) − height(right_subtree); height(node) = 1 + max(height(left), height(right))", "screen_mapping": "树根位于 SVG 顶部中央 (cx=50%, cy=10%)，每层向下偏移 20% 高度，同层节点水平均匀分布；y 轴向下为正", "invariants": ["每个节点的 BF 等于其左子树高度减右子树高度", "balanced 状态下所有节点 BF ∈ {-1,0,1}", "unbalanced_left 状态下至少一个节点 BF = 2", "unbalanced_right 状态下至少一个节点 BF = -2"]}, "verification_cases": [{"input": "treeStructure='balanced', selectedNode='root'", "expected": "根节点 h=3, BF=0；所有节点白色；根节点边框加粗"}, {"input": "treeStructure='unbalanced_left', selectedNode='root'", "expected": "根节点 h=4, BF=2（左子树高3，右子树高1）；根节点变红；左子30 h=3, BF=1；右子70 h=1, BF=0"}, {"input": "treeStructure='unbalanced_right', selectedNode='n70'", "expected": "根节点 h=4, BF=-2；右子70 h=3, BF=-1；70 节点边框加粗；根节点变红"}, {"input": "点击重置按钮后", "expected": "回到 balanced 状态，selectedNode='root'，所有节点白色，根节点边框加粗"}]}, "id": "b_bf_diagram"}], "layout": {"kind": "full"}}, "referenceMaterial": "[none provided]"}

